import React from "react";
import { Link, useLocation } from "react-router-dom";
import "./Navbar.css";
import logo from "../assets/Logo.png";

function Navbar() {
  const location = useLocation();

  return (
    <nav className="navbar">
      {/* شعار الموقع (يعود للرئيسية عند الضغط) */}
      <div className="navbar-logo">
        <Link to="/" className="logo-link">
          <img src={logo} alt="Breast Cancer Logo" className="logo-img" />
          <span className="logo-text">Breast Cancer Detection</span>
        </Link>
      </div>

      {/* روابط الصفحات */}
      <div className="navbar-links">
        <Link
          to="/"
          className={`navbar-link ${
            location.pathname === "/" ? "active-link" : ""
          }`}
        >
          الرئيسية
        </Link>

        <Link
          to="/samples"
          className={`navbar-link ${
            location.pathname === "/samples" ? "active-link" : ""
          }`}
        >
          إدخال العينات
        </Link>

        <Link
          to="/features"
          className={`navbar-link ${
            location.pathname === "/features" ? "active-link" : ""
          }`}
        >
          إدخال الخصائص
        </Link>

        <Link
          to="/results"
          className={`navbar-link ${
            location.pathname === "/results" ? "active-link" : ""
          }`}
        >
          النتائج
        </Link>
      </div>

      {/* عمود فارغ (اختياري) */}
      <div className="navbar-empty"></div>
    </nav>
  );
}

export default Navbar;
